        for row, limit in zip(grid, limits):
            # Sort the row in descending order and take up to 'limit' elements
            candidates.extend(sorted(row, reverse=True)[:limit])

        # Sort all the collected candidates in descending order
        candidates.sort(reverse=True)

        # Sum the top 'k' elements
        return sum(candidates[:k])
